mapper.select:
select  from nad_conversation
where id in
#{i}

select c.id as conversationId, c.subject, c.application_id as applicationId, c.conversation_type as conversationType, c.status, c.last_message_id as lastMessageId, c.last_message_preview as lastMessagePreview, c.last_message_at as lastMessageAt, c.last_sender_user_id as lastSenderUserId, (select count(*) from nad_message m where m.conversation_id = c.id and m.id > coalesce(me.last_read_message_id, 0) and m.sender_user_id <> me.user_id and m.deleted_at is null) as unreadCount, peer.user_id as peerUserId, peer.last_delivered_message_id as peerDeliveredMessageId, peer.last_read_message_id as peerReadMessageId from nad_conversation_participant me join nad_conversation c on c.id = me.conversation_id left join nad_conversation_participant peer on peer.id = (select min(p2.id) from nad_conversation_participant p2 where p2.conversation_id = c.id and p2.user_id <> me.user_id and p2.removed_at is null)
left join sys_user pu on pu.user_id = peer.user_id
where me.user_id = #{userId} and me.removed_at is null and c.application_id = #{applicationId} and c.id = #{conversationId}
and (pu.nick_name like concat('%', #{query}, '%') or pu.user_name like concat('%', #{query}, '%'))
order by coalesce(c.last_message_at, c.create_time) desc, c.id desc limit #{limit} offset #{offset}

mapper.update:
update nad_conversation
set last_message_id = #{messageId}, last_message_at = #{at},
    last_message_preview = #{preview}, last_sender_user_id = #{senderUserId}
where id = #{id}
